// On-demand date/week context, using the existing administrator-only feed.
let trackingMessage='',spikeToken=0;const spikeCache=new Map();
const spikeDialog=document.createElement('dialog');spikeDialog.id='spike-dialog';spikeDialog.setAttribute('aria-labelledby','spike-title');document.body.append(spikeDialog);spikeDialog.addEventListener('close',()=>{spikeToken++;});
function trackingPanel(s){const saved=trackingDates.find(t=>t.domain===s.domain),first=(s.trend||[]).filter(p=>p.sessions>0).sort((a,b)=>a.date.localeCompare(b.date))[0]?.date,conflict=saved&&first&&first<saved.start_date;return `<details class="subdetail"><summary>Analytics tracking-start date</summary><p class="muted">${saved?'Administrator-confirmed installation date: '+escape(saved.start_date)+'.':first?'First recorded session in this 90-day window: '+escape(first)+'. This is not proof of the installation date.':'Installation date is unconfirmed.'} ${conflict?'Recorded sessions exist before the confirmed date. Review the date; those positive records remain visible.':''}</p><p class="muted">Set this only from a verified installation record. Dates before the confirmed start with no recorded sessions become chart gaps, rather than zero traffic. Search Console remains independent of GA4 installation.</p><form id="tracking-form" class="logform"><label>Confirmed GA4 installation date<input name="startDate" type="date" required max="${new Date().toISOString().slice(0,10)}" value="${saved?.start_date||''}"></label><button ${trackingReady?'':'disabled'}>Save tracking date</button>${saved?'<button type="button" data-clear-tracking>Clear confirmed date</button>':''}</form><p role="status" class="muted">${escape(trackingMessage||(!trackingReady?'Shared tracking dates are loading or unavailable.':'No installation date is guessed automatically.'))}</p></details>`;}
async function loadTracking(){try{const r=await fetch('/api/portfolio-tracking',{cache:'no-store'}),p=await r.json();if(!r.ok||!p.ok)throw Error(p.error||'Tracking dates unavailable.');trackingDates=p.tracking;trackingReady=true;}catch(e){trackingMessage=e.message;trackingReady=false;}render();}
async function saveTracking(method,body){const domain=selectedDomain;try{const r=await fetch('/api/portfolio-tracking'+(method==='DELETE'?'?site='+encodeURIComponent(domain):''),{method,headers:{'Content-Type':'application/json'},body:method==='POST'?JSON.stringify(body):undefined}),p=await r.json();if(!r.ok||!p.ok)throw Error(p.error||'Could not save date.');trackingDates=p.tracking;trackingReady=true;trackingMessage=method==='DELETE'?'Confirmed date cleared; recorded activity is still shown.':'Administrator-confirmed date saved.';}catch(e){trackingMessage=e.message;}render();}
micro.addEventListener('submit',e=>{if(e.target.id!=='tracking-form')return;e.preventDefault();e.target.querySelector('button').disabled=true;saveTracking('POST',{domain:selectedDomain,startDate:new FormData(e.target).get('startDate')});});
function spikeShell(title,content){spikeDialog.innerHTML=`<header class="panelhead"><h2 id="spike-title">${escape(title)}</h2><form method="dialog"><button aria-label="Close date breakdown">Close ×</button></form></header>${content}`;}
function spikeContent(s,p,point,key){const range=point.date===point.end?point.date:point.date+' → '+point.end,description=point.partial?'Partial calendar week: only the displayed dates are requested. ':'';const changes=changeEntries.filter(e=>(e.domain===s.domain||e.domain==='portfolio')&&e.date>=point.date&&e.date<=point.end);const head=`<p class="muted">${escape(range)} · chart selection: ${number(point.value)} recorded ${key}. ${description}Table changes compare with ${escape(p.priorStart)} → ${escape(p.priorEnd)}, the preceding equal-length period.</p>`;
 const body=key==='sessions'?`<div class="detailgrid"><article><h3>Traffic sources · source / medium</h3>${gaTable(s.referrers)}</article><article><h3>Landing pages</h3>${gaTable(s.landingPages)}</article><article><h3>Countries</h3>${gaTable(s.analyticsCountries)}</article><article><h3>Devices</h3>${gaTable(s.analyticsDevices)}</article></div><p class="muted">These are GA4 reports for the selected day/week, not the overview period. Google returns limited top rows; row sums need not equal total sessions. Session counts by dimension can also differ. Landing pages are entry pages, not every viewed page.</p>`:`<div class="detailstats"><div><span class="eyebrow">Search impressions</span><strong>${number(s.search?.impressions)}</strong></div><div><span class="eyebrow">Search clicks</span><strong>${number(s.search?.clicks)}</strong></div><div><span class="eyebrow">CTR</span><strong>${pct(s.search?.impressions?s.search.clicks/s.search.impressions:null)}</strong></div></div><div class="detailgrid"><article><h3>Search queries on these dates</h3>${searchTable(s.queries)}</article><article><h3>Search pages on these dates</h3>${searchTable(s.searchPages,true)}</article></div><p class="muted">These are Search Console reports for the selected day/week. Anonymized and omitted query rows mean table totals can differ from site totals. Rankings and clicks provide context; they do not establish what caused a change.</p>`;
 return head+body+(changes.length?`<h3>Recorded changes during these dates</h3><ul>${changes.map(e=>`<li>${escape(e.date)} · ${escape(e.title)}</li>`).join('')}</ul><p class="muted">Matching timing does not prove causation.</p>`:'<p class="muted">No operational changes were logged for these dates.</p>')+`<p class="muted">Breakdown refreshed ${escape(new Date(p.updatedAt).toLocaleString())}. Fresh Google reports may differ from an earlier chart snapshot.</p>`;
}
async function explorePoint(chart){if(!['sessions','impressions'].includes(chart.dataset.trendKey))return;if(!payload||!chart.closest('#micro'))return;const domain=chart.dataset.trendSite,key=chart.dataset.trendKey,points=JSON.parse(chart.dataset.trendPoints),point=points[Number(chart.querySelector('svg').getAttribute('aria-valuenow'))],title=config.find(c=>c[1]===domain)?.[0]+' · '+(point.date===point.end?'day':'week')+' breakdown',token=++spikeToken,id=requestId;spikeShell(title,'<p role="status">Loading reports for '+escape(point.date)+(point.date===point.end?'':' → '+escape(point.end))+'…</p>');if(!spikeDialog.open)spikeDialog.showModal();if(point.value==null){spikeShell(title,'<p>No sessions recorded before the confirmed tracking start on these dates. Missing tracking is not treated as zero traffic.</p>');return;}
 const cacheKey=[id,domain,key,point.date,point.end,document.getElementById('include-tests').checked].join('|');try{let p=spikeCache.get(cacheKey);if(!p){const query=new URLSearchParams({spike:'1',site:domain,metric:key,from:point.date,to:point.end,days:document.getElementById('days').value});if(document.getElementById('include-tests').checked)query.set('tests','include');const r=await fetch('/api/portfolio?'+query,{cache:'no-store'});p=await r.json();if(!r.ok||!p.ok||!p.spike||p.start!==point.date||p.end!==point.end||p.metric!==key||p.includeTests!==document.getElementById('include-tests').checked||!p.sites?.some(s=>s.domain===domain))throw Error(p.error||'Selected-date reports unavailable. No overview-period data is substituted.');spikeCache.set(cacheKey,p);}if(token!==spikeToken||id!==requestId||!spikeDialog.open)return;spikeShell(title,spikeContent(p.sites.find(s=>s.domain===domain),p,point,key));}catch(e){if(token!==spikeToken||id!==requestId||!spikeDialog.open)return;spikeShell(title,`<p role="alert">${escape(e.message)}</p><p class="muted">Close and select the point again to retry. Period-level tables are not used as day-level data.</p>`);}}
document.addEventListener('click',e=>{if(e.target.closest('[data-clear-tracking]'))return saveTracking('DELETE');const chart=e.target.closest('.trendchart');if(!chart)return;const toggle=e.target.closest('[data-chart-window]');if(toggle){chartWindows.set(chart.dataset.trendSite+':'+chart.dataset.trendKey,toggle.dataset.chartWindow);render();return;}if(e.target.closest('.explore-point')||e.target.closest('svg'))explorePoint(chart);});
document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key)||!e.target.matches('.trendchart svg'))return;e.preventDefault();explorePoint(e.target.closest('.trendchart'));});
const resetBeforeCharts=reset;reset=()=>{spikeCache.clear();if(spikeDialog.open)spikeDialog.close();resetBeforeCharts();};
render();loadTracking();
